85	  onClose,
86	  productName,
87	  media,
88	  colourValues,
89	  selectedColourValue,
90	  imageQuality,
91	}: ZimmGalleryOverlayProps) => {
92	  const intl = useIntl();
93	  const { t } = useUiCopy();
94	  const styles = useMultiStyleConfig(ZIMM_GALLERY_OVERLAY_RECIPE, {});
95	  const { mounted } = useZimmModal({ isOpen, onClose });
