145	  // mirrors ZimmProductGallery's own IntersectionObserver sync for its compact carousel.
146	  useEffect(() => {
147	    if (!isOpen || !bodyNode) return;
148	
149	    const observer = new IntersectionObserver(
150	      (entries) => {
151	        const mostVisible = entries
152	          .filter((entry) => entry.isIntersecting)
153	          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
154	        if (!mostVisible) return;
155	        const index = itemRefs.current.indexOf(mostVisible.target as HTMLDivElement);
156	        if (index >= 0) setActiveIndex(index);
157	      },
