130	    // the currently focused element, which can land a tick after our own keydown handler's
131	    // synchronous `.focus()` call — confirmed by instrumentation: the handler's own `.focus()`
132	    // call lands correctly (document.activeElement matches immediately inside the handler), but
133	    // a synchronous assertion straight after `user.keyboard()` intermittently still sees the
134	    // pre-move element. ZimmProductGallery's own identical dot-bar test needs no such wait
135	    // because that component isn't rendered inside a focus trap.
136	    // 1000ms default timeout confirmed flaky under full-suite load (reliable in isolation) —
137	    // FocusLock's rAF reconciliation can take longer under worker contention. 3000ms gives it
138	    // real headroom without masking a genuine regression (a true failure still fails, just later).
139	    const options = { timeout: 8000 };
140	    thumb1.focus();
141	    await user.keyboard('{ArrowRight}');
142	    await waitFor(() => expect(thumb2).toHaveFocus(), options);
143	    await user.keyboard('{ArrowLeft}');
144	    await waitFor(() => expect(thumb1).toHaveFocus(), options);
145	    await user.keyboard('{ArrowLeft}');
146	    await waitFor(() => expect(thumb7).toHaveFocus(), options);
147	  });
148	});
